css:
.fx-tfade{width:min(780px,100%);text-align:center;display:grid;gap:1.6em;justify-items:center}
.fx-tfade .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.fx-tfade .qm{font:600 4.5em/.5 var(--font-heading);color:var(--accent);opacity:.5;height:.5em;margin-top:.3em}
.fx-tfade .sl{display:grid;width:100%;position:relative}
.fx-tfade .s{grid-area:1/1;display:grid;gap:1.4em;justify-items:center;opacity:0;visibility:hidden;transform:translateY(10px);transition:opacity calc(.7s/var(--speed)) ease,transform calc(.7s/var(--speed)) ease,visibility 0s linear calc(.7s/var(--speed))}
.fx-tfade .s.on{opacity:1;visibility:visible;transform:none;transition-delay:0s}
.fx-tfade blockquote{margin:0;font:500 clamp(1.25em,3.4vw,1.8em)/1.42 var(--font-heading);max-width:30em}
.fx-tfade .who{display:flex;align-items:center;gap:.8em;text-align:left}
.fx-tfade .av{width:3em;height:3em;border-radius:50%;display:grid;place-items:center;font:700 .9em var(--font-body);color:var(--on-primary);background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 50%,var(--accent)))}
.fx-tfade .av.b{background:linear-gradient(135deg,var(--accent),color-mix(in srgb,var(--accent) 50%,var(--primary)));color:var(--on-accent)}
.fx-tfade .av.c{background:linear-gradient(135deg,color-mix(in srgb,var(--primary) 60%,#000),var(--primary))}
.fx-tfade .who b{display:block}.fx-tfade .who small{opacity:.62}
.fx-tfade .ctl{display:flex;align-items:center;gap:1.1em}
.fx-tfade .ctl button{all:unset;cursor:pointer;width:2.6em;height:2.6em;border-radius:50%;border:1.5px solid var(--border);display:grid;place-items:center;transition:all calc(.2s/var(--speed))}
.fx-tfade .ctl button:hover{border-color:var(--primary);color:var(--primary)}.fx-tfade .ctl button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.fx-tfade .dots{display:flex;gap:.55em}.fx-tfade .dots button{width:.65em;height:.65em;border:0;padding:0;background:color-mix(in srgb,var(--text) 22%,transparent);position:relative;overflow:hidden}
.fx-tfade .dots button[aria-selected=true]{width:2em;border-radius:99px;background:color-mix(in srgb,var(--text) 18%,transparent)}
.fx-tfade .dots button[aria-selected=true]::after{content:"";position:absolute;inset:0;background:var(--accent);transform-origin:left;transform:scaleX(0);animation:fxtfp calc(var(--dur,6s)/var(--speed)) linear forwards}
.fx-tfade .paused .dots button[aria-selected=true]::after{animation:none;transform:scaleX(1)}
.fx-tfade .noap .dots button[aria-selected=true]::after{animation:none;transform:scaleX(1)}
@keyframes fxtfp{to{transform:scaleX(1)}}
@media(prefers-reduced-motion:reduce){.fx-tfade .s{transition:none;transform:none}}

/* touch: :hover mirrored as .is-tap */
.fx-tfade .ctl button.is-tap{border-color:var(--primary);color:var(--primary)}

