(function(){var root=document.querySelector('.fx-tfade'),sl=[].slice.call(root.querySelectorAll('.s')),ds=[].slice.call(root.querySelectorAll('.dots button')),pp=root.querySelector('[data-pp]'),i=0,tm=null,auto=!matchMedia('(prefers-reduced-motion:reduce)').matches,DUR=6000;
function show(n){i=(n+sl.length)%sl.length;sl.forEach(function(s,k){s.classList.toggle('on',k===i);s.setAttribute('aria-hidden',k!==i)});ds.forEach(function(d,k){d.setAttribute('aria-selected',k===i);d.blur;});
var a=ds[i];a.style.setProperty('--dur',DUR/1000+'s');if(auto){a.style.animation='none';void a.offsetWidth;a.style.animation=''}sched()}
function sched(){clearTimeout(tm);root.classList.toggle('noap',!auto);root.querySelector('.sl').setAttribute('aria-live',auto?'off':'polite');if(auto)tm=setTimeout(function(){show(i+1)},DUR)}
function setAuto(o){auto=o;pp.innerHTML=o?'&#10073;&#10073;':'&#9654;';pp.setAttribute('aria-label',o?'Pause autoplay':'Start autoplay');show(i)}
root.querySelectorAll('[data-d]').forEach(function(b){b.addEventListener('click',function(){show(i+ +b.dataset.d)})});
ds.forEach(function(d,k){d.addEventListener('click',function(){show(k)})});pp.addEventListener('click',function(){setAuto(!auto)});
root.addEventListener('mouseenter',function(){clearTimeout(tm);root.classList.add('paused')});root.addEventListener('mouseleave',function(){root.classList.remove('paused');sched()});
if(!auto)pp.innerHTML='&#9654;';sl.forEach(function(s,k){s.setAttribute('aria-hidden',k!==0)});show(0)})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
